def render_star_rating_svg(rating, max_stars=5, size=15):
    html = []
    for i in range(1, max_stars + 1):
        if i <= rating:
            html.append(f'<svg class="star-icon fill" width="{size}" height="{size}" viewBox="0 0 24 24" fill="#C5A059" stroke="#C5A059" stroke-width="1.5" aria-hidden="true"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>')
        else:
            html.append(f'<svg class="star-icon empty" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="#D1D5DB" stroke-width="1.5" aria-hidden="true"><polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2"/></svg>')
    return ''.join(html)
